import math
import cirq
import networkx as nx


def qaoa_maxcut_ansatz(G=None, beta=None, gamma=None):
    if G is None:
        G = nx.Graph([(0, 3), (0, 4), (1, 3), (1, 4), (2, 3), (2, 4)])

    beta = [0.0] * 5 if beta is None else list(beta)
    gamma = [0.0] * 5 if gamma is None else list(gamma)

    if len(beta) != 5 or len(gamma) != 5:
        raise ValueError("beta and gamma must each contain 5 parameters.")

    nodes = list(G.nodes())
    qubits = cirq.LineQubit.range(len(nodes))
    mapping = dict(zip(nodes, qubits))
    circuit = cirq.Circuit(cirq.H.on_each(*qubits))

    for b, g in zip(beta, gamma):
        for u, v, data in G.edges(data=True):
            if u != v:
                weight = data.get("weight", 1.0)
                circuit.append(
                    cirq.ZZPowGate(exponent=-g * weight / math.pi)(
                        mapping[u], mapping[v]
                    )
                )
        circuit.append(cirq.rx(2 * b).on_each(*qubits))

    circuit.append(cirq.measure(*qubits, key="result"))
    return circuit

