def qft_6():
    """Return a six-qubit QFT circuit with measurement key 'result'."""
    qubits = cirq.LineQubit.range(6)
    circuit = cirq.Circuit()

    for target in range(5, -1, -1):
        circuit.append(cirq.H(qubits[target]))
        for control in range(target - 1, -1, -1):
            angle = pi / (2 ** (target - control))
            circuit.append(
                cirq.CZPowGate(exponent=angle / pi)(
                    qubits[control], qubits[target]
                )
            )

    for index in range(3):
        circuit.append(cirq.SWAP(qubits[index], qubits[5 - index]))

    circuit.append(cirq.measure(*qubits, key='result'))
    return circuit

