import pennylane as qml

def grover_search_oracle_00():
    """
    Use Grover's algorithm to find |00>, returning 1000 samples.
    """
    dev = qml.device("default.qubit", wires=2, shots=1000)

    @qml.qnode(dev)
    def circuit():
        for wire in range(2):
            qml.Hadamard(wires=wire)

        # Oracle: flip the phase of |00>.
        for wire in range(2):
            qml.PauliX(wires=wire)
        qml.CZ(wires=[0, 1])
        for wire in range(2):
            qml.PauliX(wires=wire)

        # Grover diffusion operator (up to a global phase).
        for wire in range(2):
            qml.Hadamard(wires=wire)
            qml.PauliX(wires=wire)
        qml.CZ(wires=[0, 1])
        for wire in range(2):
            qml.PauliX(wires=wire)
            qml.Hadamard(wires=wire)

        return qml.sample()

    return circuit()

