def swaptest_zaxis(unknown_state):
    """Return 1000 SWAP-test samples comparing unknown_state with |0⟩."""
    dev = qml.device("default.qubit", wires=3, shots=1000)
    prepare_state = qml.from_qiskit(unknown_state)

