def qpe_x_gate():
    dev = qml.device("default.qubit", wires=4, shots=1000)

    @qml.qnode(dev)
    def circuit():
        qml.PauliX(wires=3)
        qml.Hadamard(wires=3)

        for wire in range(3):
            qml.Hadamard(wires=wire)
            for _ in range(2 ** (2 - wire)):
