def VQE_Z2(param):
    """Optimize a two-qubit ZZ Hamiltonian and return 1000 bit samples."""
    angles = np.asarray(param, dtype=float)
    if angles.ndim != 1 or angles.size == 0:
        raise ValueError('param must be a nonempty one-dimensional list of angles')
    if not np.all(np.isfinite(angles)):
        raise ValueError('param must contain finite angles')

    energy_device = qml.device('default.qubit', wires=2)
    sample_device = qml.device('default.qubit', wires=2, shots=1000)
    hamiltonian = qml.PauliZ(0) @ qml.PauliZ(1)

    def ansatz(theta):
        for index, angle in enumerate(theta):
            qml.RY(angle, wires=index % 2)
        qml.CNOT(wires=[0, 1])

    @qml.qnode(energy_device)
    def energy(theta):
        ansatz(theta)
        return qml.expval(hamiltonian)

    result = minimize(
        lambda theta: float(energy(theta)),
        angles.copy(),
        method='Powell',
        options={'maxiter': 1000, 'xtol': 1e-9, 'ftol': 1e-10},
    )

    @qml.qnode(sample_device)
    def sample_ground_state(theta):
        ansatz(theta)
        return qml.sample(wires=[0, 1])

    return sample_ground_state(result.x)

