def qaoa_maxcut_ansatz(G, beta, gamma) -> QuantumCircuit:
    """Construct and measure a five-layer QAOA MaxCut circuit."""
    if len(beta) != 5 or len(gamma) != 5:
        raise ValueError("beta and gamma must each contain five parameters.")

    nodes = list(G.nodes())
    n = len(nodes)
    if set(nodes) == set(range(n)):
        node_index = {node: node for node in nodes}
    else:
        node_index = {node: i for i, node in enumerate(nodes)}

    qr = QuantumRegister(n, "q")
    cr = ClassicalRegister(n, "c")
    circuit = QuantumCircuit(qr, cr)
    circuit.h(qr)

    for layer in range(5):
        for u, v in G.edges():
            if u != v:
                circuit.rzz(2 * gamma[layer], qr[node_index[u]], qr[node_index[v]])
        for qubit in qr:
            circuit.rx(2 * beta[layer], qubit)

    circuit.measure(qr, cr)
    return circuit

